function sorted(rows) { const k = state.sort, d = state.dir === 'asc' ? 1 : -1; return [...rows].sort((a,b) => { let x = a[k], y = b[k]; if (k === 'status') { x = STATUS[a.status][2]; y = STATUS[b.status][2]; } if (k === 'start') { x = a.start || '9999'; y = b.start || '9999'; } if (x == null) return 1; if (y == null) return -1; return (x > y ? 1 : x < y ? -1 : 0) * d; }); }
